def f(x, y, z):
    """Calculates x^3 + y^3 + z^3 - x^2*y^2*z^2"""
    return x**3 + y**3 + z**3 - (x**2) * (y**2) * (z**2)

solutions = []
MAX_VAL = 10 # Limiting the search space for the initial systematic search

print(f"Starting search for solutions (x, y, z) for f(x, y, z) = 0 with x <= y <= z up to MAX_VAL={MAX_VAL}")

for x in range(1, MAX_VAL + 1):
    for y in range(x, MAX_VAL + 1):
        for z in range(y, MAX_VAL + 1):
            if f(x, y, z) == 0:
                solutions.append((x, y, z))

if solutions:
    print("\nFound solutions:")
    for sol in solutions:
        print(sol)
else:
    print("\nNo solutions found within the search bounds.")

